                            ...styles.toast,
                            ...(toast.type === "success"
                                ? styles.toastSuccess
                                : toast.type === "error"
                                    ? styles.toastError
                                    : styles.toastInfo),
                        }}
                    >
                        {toast.message}
                    </div>
                ))}
            </div>

            {/* NAVBAR */}
