                                        style={styles.titleInput}
                                    />
                                ) : (
                                    study.title
                                )}
                            </h1>

                            <div style={styles.badgeGroup}>
                                <span
                                    style={{
                                        ...styles.statusBadge,
                                        background: theme.badgeBg,
                                        color: theme.badgeColor,
                                    }}
                                >
                                    {study.status}
                                </span>

                                <span style={styles.visibilityBadge}>
                                    {study.visibility}
                                </span>
                            </div>
                        </div>

                        {/* DESCRIPTION */}
                        <div style={styles.descriptionSection}>
                            <label style={styles.label}>Description</label>

                            {isEditing ? (
                                <textarea
                                    value={editedStudy.description}
                                    onChange={(e) =>
                                        setEditedStudy({
                                            ...editedStudy,
                                            description: e.target.value,
                                        })
                                    }
                                    style={styles.descriptionTextarea}
                                />
                            ) : (
                                <p style={styles.studyDescription}>
                                    {study.description}
                                </p>
                            )}
                        </div>

                        {/* INFO ROW */}
                        <div style={styles.infoRow}>
                            <div style={styles.infoItem}>
                                <span style={styles.infoLabel}>
                                    👥 Participants:
                                </span>
                                <span style={styles.infoValue}>
                                    {study.participants?.length || 0}
                                </span>
                            </div>

                            <div style={styles.infoItem}>
                                <span style={styles.infoLabel}>🕒 Created:</span>
                                <span style={styles.infoValue}>
                                    {new Date(
                                        study.createdAt
                                    ).toLocaleDateString()}
                                </span>
                            </div>
                        </div>

                        {/* EDIT BUTTON */}
                        {!isEditing && permissions.canEditStudy && (
                            <button style={styles.editButton} onClick={handleEdit}>
                                Edit Study Details
                            </button>
                        )}
                    </div>

                    {/* QUIZ CARD */}
                    <div style={styles.quizCard}>
                        <div style={styles.quizHeader}>
                            <div style={styles.quizIcon}>📝</div>
                            <h2 style={styles.quizTitle}>Study Quiz</h2>
                        </div>

                        <h3 style={styles.quizName}>
                            {study.quiz?.title || "No quiz assigned"}
                        </h3>

                        <div style={styles.quizDetails}>
                            <div style={styles.quizDetailItem}>
                                <span style={styles.quizDetailLabel}>
                                    Questions:
                                </span>
                                <span style={styles.quizDetailValue}>
                                    {study.quiz?.questionCount || 0}
                                </span>
                            </div>

                            <div style={styles.quizDetailItem}>
                                <span style={styles.quizDetailLabel}>
                                    Last Updated:
                                </span>
                                <span style={styles.quizDetailValue}>
                                    {study.quiz?.lastUpdated
                                        ? new Date(
                                            study.quiz.lastUpdated
                                        ).toLocaleDateString()
                                        : "-"}
                                </span>
                            </div>
                        </div>

                        {isOwner && (
                            <button
                                style={styles.manageQuizButton}
                                onClick={handleManageQuiz}
                            >
                                Manage Quiz
                            </button>
                        )}
                    </div>
                </div>

                {/* STATUS / VISIBILITY / DATE */}
                <div style={styles.threeColumnSection}>
                    {/* STATUS */}
                    <div style={styles.section}>
                        <h2 style={styles.sectionTitle}>Study Status</h2>
                        <p style={styles.sectionDescription}>
                            Change the current status
                        </p>

                        <div
                            style={styles.visibilityContainer}
                            ref={statusMenuRef}
                        >
                            <button
                                style={{
                                    ...styles.visibilityButton,
                                    ...(!isOwner ? styles.visibilityButtonDisabled : {})
                                }}
                                onClick={() => isOwner && setShowStatusMenu((s) => !s)}
                            >
                                <span style={styles.visibilityButtonText}>
                                    {
                                        getStatusDisplay(
                                            study.status
                                        ).icon
                                    }{" "}
                                    {
                                        getStatusDisplay(
                                            study.status
                                        ).label
                                    }
                                </span>

                                <span style={styles.dropdownArrow}>
                                    {showStatusMenu ? "▲" : "▼"}
                                </span>
                            </button>

                            {showStatusMenu && (
                                <div style={styles.visibilityMenu}>
                                    {["DRAFT", "ACTIVE", "COMPLETED", "ARCHIVED"].map(
                                        (s) => (
                                            <div
                                                key={s}
                                                style={{
                                                    ...styles.visibilityOption,
                                                    background:
                                                        study.status === s
                                                            ? "rgba(255,255,255,0.06)"
                                                            : "transparent",
                                                }}
                                                onClick={() =>
                                                    handleStatusChange(s)
                                                }
                                            >
                                                <span
                                                    style={styles.visibilityIcon}
                                                >
                                                    {
                                                        getStatusDisplay(
                                                            s
                                                        ).icon
                                                    }
                                                </span>

                                                <div>
                                                    <div
                                                        style={
                                                            styles.visibilityOptionTitle
                                                        }
                                                    >
                                                        {
                                                            getStatusDisplay(
                                                                s
                                                            ).label
                                                        }
                                                    </div>

                                                    <div
                                                        style={
                                                            styles.visibilityOptionDesc
                                                        }
                                                    >
                                                        {s === "DRAFT" &&
                                                            "Study is in preparation"}
                                                        {s === "ACTIVE" &&
                                                            "Study is running"}
                                                        {s === "COMPLETED" &&
                                                            "Study has ended"}
                                                        {s === "ARCHIVED" &&
                                                            "Study is archived"}
                                                    </div>
                                                </div>
                                            </div>
                                        )
                                    )}
                                </div>
                            )}
                        </div>
                    </div>

                    {/* VISIBILITY */}
                    <div style={styles.section}>
                        <h2 style={styles.sectionTitle}>Visibility</h2>
                        <p style={styles.sectionDescription}>
