                        </p>

                        <div
                            style={styles.visibilityContainer}
                            ref={visibilityMenuRef}
                        >
                            <button
                                style={{
                                    ...styles.visibilityButton,
                                    ...(!isOwner ? styles.visibilityButtonDisabled : {})
                                }}
                                onClick={() => isOwner && setShowVisibilityMenu((s) => !s)}
                            >
                                <span style={styles.visibilityButtonText}>
                                    {study.visibility === "PUBLIC"
                                        ? "🌍 Public"
                                        : "🔐 Private"}
                                </span>

                                <span style={styles.dropdownArrow}>
                                    {showVisibilityMenu ? "▲" : "▼"}
                                </span>
                            </button>

                            {showVisibilityMenu && (
                                <div style={styles.visibilityMenu}>
                                    <div
                                        style={{
                                            ...styles.visibilityOption,
                                            background:
                                                study.visibility === "PUBLIC"
                                                    ? "rgba(255,255,255,0.06)"
                                                    : "transparent",
                                        }}
                                        onClick={() =>
                                            handleVisibilitySelect("PUBLIC")
                                        }
                                    >
                                        <span style={styles.visibilityIcon}>
                                            🌍
                                        </span>
                                        <div>
                                            <div
                                                style={
                                                    styles.visibilityOptionTitle
                                                }
                                            >
                                                Public
                                            </div>
                                            <div
                                                style={
                                                    styles.visibilityOptionDesc
                                                }
                                            >
                                                Anyone can view the study.
                                            </div>
                                        </div>
                                    </div>

                                    <div
                                        style={{
                                            ...styles.visibilityOption,
                                            background:
                                                study.visibility === "PRIVATE"
                                                    ? "rgba(255,255,255,0.06)"
                                                    : "transparent",
                                            borderBottom: "none",
                                        }}
                                        onClick={() =>
                                            handleVisibilitySelect("PRIVATE")
                                        }
                                    >
                                        <span style={styles.visibilityIcon}>
                                            🔐
                                        </span>
                                        <div>
                                            <div
                                                style={
                                                    styles.visibilityOptionTitle
                                                }
                                            >
                                                Private
                                            </div>
                                            <div
                                                style={
                                                    styles.visibilityOptionDesc
                                                }
                                            >
                                                Only you can view the study.
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* END DATE */}
                    <div style={styles.section}>
